content.text:
            return "FRAME_ENCODING_ERROR"
        if end > self.crypto_limit:
            return "CRYPTO_BUFFER_EXCEEDED"
        err = st.store(off, data, self.keep_first, undo)
        if err is not None:
            return err
        if end > st.highest:
            undo.append((st, "chighest", st.highest))
            st.highest = end
        st.advance(undo)
        return None

    def _stream(self, fr):
        sid = fr["id"]
        m = sid & 3
        if m != 0 and m != 2:
            return "STREAM_STATE_ERROR"
        limit = self.max_bidi if m == 0 else self.max_uni
        if (sid >> 2) + 1 > limit:
            return "STREAM_LIMIT_ERROR"
        st = self._get_stream(sid)
        data = bytes.fromhex(fr["data_hex"])
        off = fr["offset"]
        end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        fs = st.final_size
        fin = fr["fin"]
        if fs is not None:
            if end > fs or (fin and end != fs):
                return "FINAL_SIZE_ERROR"
        if fin and end < st.highest:
            return "FINAL_SIZE_ERROR"
        if end > self.max_stream_data:
            return "FLOW_CONTROL_ERROR"
        new_high = end if end > st.highest else st.highest
        if self.received_total - st.highest + new_high > self.max_data:
            return "FLOW_CONTROL_ERROR"
        if not st.reset:
            err = st.store(off, data, self.keep_first, self.undo)
            if err is not None:
                return err
        if new_high > st.highest:
            self.received_total += new_high - st.highest
            st.highest = new_high
        if fin:
            st.final_size = end
        st.advance(self.undo)
        return None

    def _reset(self, fr):
        sid = fr["id"]
        m = sid & 3
        if m != 0 and m != 2:
            return "STREAM_STATE_ERROR"
        limit = self.max_bidi if m == 0 else self.max_uni
        if (sid >> 2) + 1 > limit:
            return "STREAM_LIMIT_ERROR"
        st = self._get_stream(sid)
        fs = fr["final_size"]
        if st.final_size is not None and st.final_size != fs:
            return "FINAL_SIZE_ERROR"
        if fs < st.highest:
            return "FINAL_SIZE_ERROR"
        if fs > self.max_stream_data:
            return "FLOW_CONTROL_ERROR"
        new_high = fs if fs > st.highest else st.highest
        if self.received_total - st.highest + new_high > self.max_data:
            return "FLOW_CONTROL_ERROR"
        if new_high > st.highest:
            self.received_total += new_high - st.highest
            st.highest = new_high
        st.final_size = fs
        st.reset = True
        return None

    def _stop(self, fr):
        sid = fr["id"]
        if sid & 3 != 0:
            return "STREAM_STATE_ERROR"
        if (sid >> 2) + 1 > self.max_bidi:
            return "STREAM_LIMIT_ERROR"
        st = self._get_stream(sid)
        st.stopped = True
        return None

    # -- output ------------------------------------------------------------

    def build(self, tid):
        ordered = sorted(self.results, key=lambda r: (r[0], r[1]))
        packets = [r[2] for r in ordered]
        conn = {
            "state": self.state,
            "code": self.code,
            "at_ms": self.at_ms,
            "source": self.source,
            "peer_code": self.peer_code,
            "last_activity_ms": self.last_activity,
        }
        keys = {
            "I": self.keys["I"],
            "H": self.keys["H"],
            "Z": self.keys["Z"],
            "A": self.keys["A"],
        }
        streams = []
        for sid in sorted(self.streams):
            st = self.streams[sid]
            streams.append({
                "id": sid,
                "highest": st.highest,
                "final_size": st.final_size,
                "reset": st.reset,
                "stopped": st.stopped,
                "delivered_hex": st.prefix_hex(),
            })
        crypto = []
        for lv in ("I", "H", "A"):
            st = self.crypto[lv]
            crypto.append({
                "level": lv,
                "highest": st.highest,
                "contiguous_hex": st.prefix_hex(),
            })
        return {
            "id": tid,
            "packets": packets,
            "connection": conn,
            "keys": keys,
            "received_total": self.received_total,
            "streams": streams,
            "crypto": crypto,
        }


# --------------------------------------------------------------------------
# entry point
# --------------------------------------------------------------------------

def _emit(obj):
    sys.stdout.write(json.dumps(obj))
    sys.stdout.write("\n")
    sys.stdout.flush()


def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
        return 0
    try:
        doc = _parse(raw)
        _validate(doc)
    except Invalid:
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
        return 0
    try:
        results = []
        for tr in doc["traces"]:
            sim = Sim(tr["config"])
            sim.run(tr["events"])
            results.append(sim.build(tr["id"]))
        _emit({"version": 1, "results": results})
    except Exception as exc:  # pragma: no cover - defensive only
        sys.stderr.write("internal error: %r\n" % (exc,))
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
    return 0


if __name__ == "__main__":
    sys.exit(main())
